    "com.unity.modules.physics": "1.0.0",
    "com.unity.modules.physics2d": "1.0.0"
  }
}
with open(manifest_path, "w") as f:
    json.dump(manifest, f, indent=2)
print("MANIFEST_WRITTEN")
