rm -f "$PROJ/Packages/packages-lock.json"

echo "=== PURGE STALE SCRIPTS (compile poison from older jobs) ==="
rm -f "$PROJ/Assets/Editor/LevelBuilder.cs"
rm -f "$PROJ/Assets/Editor/LevelLayout.cs"
rm -f "$PROJ/Assets/Editor/PoissonDiskSampler.cs"
echo "STALE_PURGED"

echo "=== OFFLINE MODE (play HeistLevel directly, no Photon AppId; proven t1-5 recipe) ==="
