mkdir -p /tmp/xdg; chmod 700 /tmp/xdg
export XDG_RUNTIME_DIR=/tmp/xdg
printf 'pcm.!default { type null }\nctl.!default { type null }\n' > /etc/asound.conf || true

echo "=== GENERATE LEVEL LAYOUT ASSET ==="
"$UNITY" -batchmode -nographics -quit -projectPath "$PROJ" -executeMethod LevelLayoutGenerator.Generate -logFile /content/levellayout_gen.log 2>&1 || true
if grep -q "Aborting batchmode" /content/levellayout_gen.log 2>/dev/null; then
  echo "GEN_FAIL"
  grep -n "error CS\|Exception\|Aborting batchmode" /content/levellayout_gen.log | head -25
  tail -10 /content/levellayout_gen.log
  exit 6
fi
if [ ! -f "$PROJ/Assets/Resources/LevelLayout.asset" ]; then
  echo "ASSET_MISSING"
  tail -20 /content/levellayout_gen.log
  exit 6
fi
echo "ASSET_OK"

echo "=== BUILD LEVEL SCENE + MFPS WIRING ==="
rm -f "$PROJ/Assets/MFPS/Scenes/HeistLevel.unity"
"$UNITY" -batchmode -nographics -quit -projectPath "$PROJ" -executeMethod LevelBuilder.BuildFromLayoutAsset -logFile /content/level_build.log 2>&1 || true
if grep -q "Aborting batchmode" /content/level_build.log 2>/dev/null; then
  echo "LEVEL_BUILD_FAIL"
  grep -n "error CS\|Exception\|Aborting batchmode" /content/level_build.log | head -25
  tail -10 /content/level_build.log
  exit 6
fi
if [ ! -f "$PROJ/Assets/MFPS/Scenes/HeistLevel.unity" ]; then
  echo "SCENE_MISSING"
  tail -20 /content/level_build.log
  exit 6
fi
grep -E "LEVEL_BUILDER: (scene saved|wired|spawn)" /content/level_build.log | head -20
echo "LEVEL_SCENE_OK"

echo "=== BUILD WINDOWS ==="
"$UNITY" -batchmode -nographics -quit -projectPath "$PROJ" -executeMethod MfpsBuild.BuildWindows -logFile /content/win_build.log 2>&1 || true
if grep -q "Aborting batchmode" /content/win_build.log 2>/dev/null; then
  echo "WIN_FAIL_ABORT"
  grep -n "error CS\|Exception\|Aborting batchmode" /content/win_build.log | head -25
  exit 6
fi
if ! grep -q "BUILD_RESULT Succeeded" /content/win_build.log 2>/dev/null; then
  echo "WIN_BUILD_FAIL"
  grep -n "BUILD_FAILED\|BUILD_MSG\|Exception" /content/win_build.log | head -20
  tail -10 /content/win_build.log
  exit 6
fi
grep -n "BUILD_RESULT" /content/win_build.log | tail -1

echo "=== STAGE ==="
STAMP=$(date +%s)
BUNDLE="$PROJ/Builds/Win"
if [ ! -f "$BUNDLE/MFPSPrototype.exe" ]; then echo "NO_EXE"; exit 6; fi
cd "$PROJ" && zip -qr "/tmp/mfps-level-$STAMP.zip" "Builds/Win" && echo "ZIPPED"
ls -lh "/tmp/mfps-level-$STAMP.zip"
mkdir -p "$MFPSROOT/builds"
cp "/tmp/mfps-level-$STAMP.zip" "$MFPSROOT/builds/mfps-level-$STAMP.zip" && echo "STAGED_OK"
echo "MFPS_LEVEL_ZIP=mfps-level-$STAMP.zip"
mkdir -p "$MFPSROOT/templates/mfps-2.0-v1.75"
cp "$PROJ/Assets/Editor/LevelLayout.cs" "$PROJ/Assets/Editor/LevelBuilder.cs" "$PROJ/Assets/Editor/PerfTune.cs" "$MFPSROOT/templates/mfps-2.0-v1.75/" 2>/dev/null && echo "SCRIPTS_CACHED_TO_DRIVE" || echo "SCRIPTS_CACHE_SKIPPED"
echo "LEVEL_BUILD_COMPLETE"
